{-| @Pudu.Backend.Runtime.Float.Format — locked GHC-compatible binary64 text.
    Upstream attribution and terms are retained in THIRD_PARTY_NOTICES. -}
module Pudu.Backend.Runtime.Float.Format
  ( floatFormatRuntimeParts, floatFormatRuntimeDependencies ) where

import Data.Text (Text)
import Pudu.Backend.Runtime.Float.Natural (floatNaturalRuntimeParts, floatNaturalRuntimeDependencies)

floatFormatRuntimeParts :: [(Text, [Text])]
floatFormatRuntimeParts = floatNaturalRuntimeParts <>
  [ ("float_notice",
      [ "/*"
      , "GHC binary64 formatting"
      , ""
      , "Pudu.Backend.Runtime.Float.Format adapts floatToDigits and formatRealFloatAlt"
      , "from GHC.Internal.Float in GHC 9.14.1."
      , "Source: https://github.com/ghc/ghc/blob/ghc-9.14.1-release/libraries/ghc-internal/src/GHC/Internal/Float.hs"
      , "Upstream source copyright: (c) The University of Glasgow 1994-2002."
      , "Portions obtained from hbc (c) Lennart Augusstson."
      , ""
      , "The Glasgow Haskell Compiler License"
      , ""
      , "Copyright 2002, The University Court of the University of Glasgow."
      , "All rights reserved."
      , ""
      , "Redistribution and use in source and binary forms, with or without"
      , "modification, are permitted provided that the following conditions are met:"
      , ""
      , "- Redistributions of source code must retain the above copyright notice,"
      , "this list of conditions and the following disclaimer."
      , ""
      , "- Redistributions in binary form must reproduce the above copyright notice,"
      , "this list of conditions and the following disclaimer in the documentation"
      , "and/or other materials provided with the distribution."
      , ""
      , "- Neither name of the University nor the names of its contributors may be"
      , "used to endorse or promote products derived from this software without"
      , "specific prior written permission."
      , ""
      , "THIS SOFTWARE IS PROVIDED BY THE UNIVERSITY COURT OF THE UNIVERSITY OF"
      , "GLASGOW AND THE CONTRIBUTORS \"AS IS\" AND ANY EXPRESS OR IMPLIED WARRANTIES,"
      , "INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND"
      , "FITNESS FOR A PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE"
      , "UNIVERSITY COURT OF THE UNIVERSITY OF GLASGOW OR THE CONTRIBUTORS BE LIABLE"
      , "FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL"
      , "DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR"
      , "SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER"
      , "CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT"
      , "LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY"
      , "OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH"
      , "DAMAGE."
      , "*/"
      ])
  , ("float_require",
      [ "static inline void pudu_float_require(int success) {"
      , "  if (!success) abort();"
      , "}"
      ])
  , ("float_decimal",
      [ "typedef struct { char digits[24]; size_t length; int32_t exponent; } pudu_float_digits;"
      , "static inline pudu_float_nat pudu_float_scaled_word(uint64_t word, uint32_t shift) {"
      , "  pudu_float_nat result = {0};"
      , "  pudu_float_require(pudu_float_nat_from_shift(&result, word, shift));"
      , "  return result;"
      , "}"
      , "static inline pudu_float_digits pudu_float_decimal(uint64_t magnitude) {"
      , "  pudu_float_require(magnitude != 0 && magnitude < UINT64_C(0x7ff0000000000000));"
      , "  uint32_t exponent = (uint32_t)(magnitude >> 52);"
      , "  uint64_t f = magnitude & UINT64_C(0x000fffffffffffff);"
      , "  int32_t e, lx;"
      , "  if (exponent != 0) {"
      , "    f |= UINT64_C(1) << 52; e = (int32_t)exponent - 1075; lx = (int32_t)exponent - 1023;"
      , "  } else {"
      , "    e = -1074; lx = -1074;"
      , "    for (uint64_t word = f; word > 1; word >>= 1) ++lx;"
      , "  }"
      , "  pudu_float_nat r, s, upper, lower;"
      , "  if (e >= 0) {"
      , "    if (f == (UINT64_C(1) << 52)) {"
      , "      r = pudu_float_scaled_word(f, (uint32_t)(e + 2)); s = pudu_float_scaled_word(4, 0);"
      , "      upper = pudu_float_scaled_word(1, (uint32_t)(e + 1)); lower = pudu_float_scaled_word(1, (uint32_t)e);"
      , "    } else {"
      , "      r = pudu_float_scaled_word(f, (uint32_t)(e + 1)); s = pudu_float_scaled_word(2, 0);"
      , "      upper = pudu_float_scaled_word(1, (uint32_t)e); lower = upper;"
      , "    }"
      , "  } else if (e > -1074 && f == (UINT64_C(1) << 52)) {"
      , "    r = pudu_float_scaled_word(f, 2); s = pudu_float_scaled_word(1, (uint32_t)(-e + 2));"
      , "    upper = pudu_float_scaled_word(2, 0); lower = pudu_float_scaled_word(1, 0);"
      , "  } else {"
      , "    r = pudu_float_scaled_word(f, 1); s = pudu_float_scaled_word(1, (uint32_t)(-e + 1));"
      , "    upper = pudu_float_scaled_word(1, 0); lower = upper;"
      , "  }"
      , "  int32_t k = (lx * 8651) / 28738 + (lx >= 0 ? 1 : 0);"
      , "  pudu_float_require(k >= -323 && k <= 309);"
      , "  pudu_float_nat bound = {0};"
      , "  pudu_float_require(pudu_float_nat_add(&bound, &r, &upper));"
      , "  for (;;) {"
      , "    pudu_float_nat left = bound, right = s;"
      , "    if (k >= 0) pudu_float_require(pudu_float_nat_scale10(&right, &s, (uint32_t)k));"
      , "    else pudu_float_require(pudu_float_nat_scale10(&left, &bound, (uint32_t)-k));"
      , "    if (pudu_float_nat_compare(&left, &right) <= 0) break;"
      , "    ++k; pudu_float_require(k <= 309);"
      , "  }"
      , "  if (k >= 0) pudu_float_require(pudu_float_nat_scale10(&s, &s, (uint32_t)k));"
      , "  else {"
      , "    pudu_float_require(pudu_float_nat_scale10(&r, &r, (uint32_t)-k));"
      , "    pudu_float_require(pudu_float_nat_scale10(&upper, &upper, (uint32_t)-k));"
      , "    pudu_float_require(pudu_float_nat_scale10(&lower, &lower, (uint32_t)-k));"
      , "  }"
      , "  pudu_float_digits result = {0};"
      , "  for (;;) {"
      , "    /* Binary64 scaling and 24 digit steps stay below 1210 bits. */"
      , "    pudu_float_require(result.length < sizeof result.digits);"
      , "    pudu_float_nat scaled = {0}, remainder = {0}, next_upper = {0}, next_lower = {0}, upper_sum = {0};"
      , "    unsigned digit = 0;"
      , "    pudu_float_require(pudu_float_nat_multiply_small(&scaled, &r, 10));"
      , "    pudu_float_require(pudu_float_nat_digit(&remainder, &digit, &scaled, &s));"
      , "    pudu_float_require(pudu_float_nat_multiply_small(&next_upper, &upper, 10));"
      , "    pudu_float_require(pudu_float_nat_multiply_small(&next_lower, &lower, 10));"
      , "    pudu_float_require(pudu_float_nat_add(&upper_sum, &remainder, &next_upper));"
      , "    /* GHC excludes midpoint boundaries when choosing its last digit. */"
      , "    int near_lower = pudu_float_nat_compare(&remainder, &next_lower) < 0;"
      , "    int near_upper = pudu_float_nat_compare(&upper_sum, &s) > 0;"
      , "    if (near_lower || near_upper) {"
      , "      if (near_upper) {"
      , "        pudu_float_nat twice = {0};"
      , "        pudu_float_require(pudu_float_nat_multiply_small(&twice, &remainder, 2));"
      , "        if (!near_lower || pudu_float_nat_compare(&twice, &s) >= 0) ++digit;"
      , "      }"
      , "      pudu_float_require(digit < 10);"
      , "      result.digits[result.length++] = (char)('0' + digit); break;"
      , "    }"
      , "    result.digits[result.length++] = (char)('0' + digit);"
      , "    r = remainder; upper = next_upper; lower = next_lower;"
      , "  }"
      , "  result.exponent = k; return result;"
      , "}"
      ])
  , ("float_format",
      [ "static inline void pudu_float_append(char output[32], size_t *count, char byte) {"
      , "  pudu_float_require(*count < 31); output[(*count)++] = byte;"
      , "}"
      , "static inline size_t pudu_format_float64(uint64_t bits, char output[32]) {"
      , "  uint64_t magnitude = bits & UINT64_C(0x7fffffffffffffff);"
      , "  size_t count = 0;"
      , "  if (magnitude > UINT64_C(0x7ff0000000000000)) { memcpy(output, \"NaN\", 3); return 3; }"
      , "  if ((bits >> 63) != 0) pudu_float_append(output, &count, '-');"
      , "  if (magnitude == UINT64_C(0x7ff0000000000000)) { memcpy(output + count, \"Infinity\", 8); return count + 8; }"
      , "  if (magnitude == 0) { memcpy(output + count, \"0.0\", 3); return count + 3; }"
      , "  pudu_float_digits decimal = pudu_float_decimal(magnitude);"
      , "  if (decimal.exponent < 0 || decimal.exponent > 7) {"
      , "    pudu_float_append(output, &count, decimal.digits[0]); pudu_float_append(output, &count, '.');"
      , "    if (decimal.length == 1) pudu_float_append(output, &count, '0');"
      , "    else for (size_t i = 1; i < decimal.length; ++i) pudu_float_append(output, &count, decimal.digits[i]);"
      , "    pudu_float_append(output, &count, 'e');"
      , "    int32_t exponent = decimal.exponent - 1;"
      , "    if (exponent < 0) { pudu_float_append(output, &count, '-'); exponent = -exponent; }"
      , "    char reversed[4]; size_t length = 0;"
      , "    do { reversed[length++] = (char)('0' + exponent % 10); exponent /= 10; } while (exponent != 0);"
      , "    while (length != 0) pudu_float_append(output, &count, reversed[--length]);"
      , "  } else if (decimal.exponent <= 0) {"
      , "    pudu_float_append(output, &count, '0'); pudu_float_append(output, &count, '.');"
      , "    for (int32_t i = 0; i < -decimal.exponent; ++i) pudu_float_append(output, &count, '0');"
      , "    for (size_t i = 0; i < decimal.length; ++i) pudu_float_append(output, &count, decimal.digits[i]);"
      , "  } else {"
      , "    size_t whole = (size_t)decimal.exponent;"
      , "    for (size_t i = 0; i < whole; ++i) pudu_float_append(output, &count, i < decimal.length ? decimal.digits[i] : '0');"
      , "    pudu_float_append(output, &count, '.');"
      , "    if (whole >= decimal.length) pudu_float_append(output, &count, '0');"
      , "    else for (size_t i = whole; i < decimal.length; ++i) pudu_float_append(output, &count, decimal.digits[i]);"
      , "  }"
      , "  return count;"
      , "}"
      ])
  ]

floatFormatRuntimeDependencies :: Text -> [Text]
floatFormatRuntimeDependencies name = floatNaturalRuntimeDependencies name <> maybe [] id (lookup name
  [ ("float_decimal", ["float_notice", "float_require", "float_nat_from_shift", "float_nat_compare", "float_nat_add", "float_nat_multiply_small", "float_nat_scale10", "float_nat_digit"])
  , ("float_format", ["float_decimal"])
  ])
